	for _, item := range raw {
		row, ok := item.(map[string]any)
		if !ok {
			t.Fatalf("batch row is not an object: %v", item)
		}
		rows = append(rows, row)
	}
	return rows
}

func batchRecordBody(environment, version, batchID, gate string, changes ...string) string {
	entries := make([]string, 0, len(changes))
	for i, title := range changes {
		entries = append(entries, fmt.Sprintf(
			`{"sequence":%d,"category":"feature","title":%q,"description":"desc %s"}`,
			i+1, title, title))
	}
	return fmt.Sprintf(
		`{"environment":%q,"version":%q,"batch_id":%q,"changes":[%s],"gate_status":%q,"rollback_point":"snap:0"}`,
		environment, version, batchID, strings.Join(entries, ","), gate)
}

func mustStringSlice(t *testing.T, value any) []string {
	t.Helper()
	raw, ok := value.([]any)
	if !ok {
		t.Fatalf("expected array, got %v", value)
	}
	out := make([]string, 0, len(raw))
	for _, item := range raw {
		out = append(out, item.(string))
	}
	return out
}

// seedBatchScenario registers dev/prod and writes three batches plus one
// unbatched record:
//   b-two: dev 2.0.0 allowed (2 changes), prod 2.0.0 blocked (1 change)
//   b-one: dev 1.0.0 allowed (1 change), prod 1.0.0 pending (1 change)
//   b-old: dev 0.9.0 blocked (1 change)
// Records within each batch are created dev-first then prod so the last
// recorded_at of each batch reflects creation order.
func seedBatchScenario(t *testing.T, router *gin.Engine) {
	t.Helper()
	registerEnvironmentOK(t, router, "dev")
	registerEnvironmentOK(t, router, "prod")
	createRecordOK(t, router, batchRecordBody("dev", "0.9.0", "b-old", "blocked", "old"))
	createRecordOK(t, router, batchRecordBody("dev", "1.0.0", "b-one", "allowed", "alpha"))
	createRecordOK(t, router, batchRecordBody("prod", "1.0.0", "b-one", "pending", "alpha"))
	createRecordOK(t, router, batchRecordBody("dev", "2.0.0", "b-two", "allowed", "beta", "gamma"))
	createRecordOK(t, router, batchRecordBody("prod", "2.0.0", "b-two", "blocked", "gamma"))
	createRecordOK(t, router, withVersion(validRecordBody, "9.9.9"))
}

func TestListReleaseBatchesSummariesAndOrder(t *testing.T) {
	router := newTestRouter(t)
	seedBatchScenario(t, router)

	recorder := doRequest(t, router, http.MethodGet, "/api/v1/release-batches", "")
	if recorder.Code != http.StatusOK {
		t.Fatalf("status = %d, want 200 (body %s)", recorder.Code, recorder.Body.String())
	}
	body := decodeBatchesBody(t, recorder)
	if body["next_cursor"] != nil {
		t.Fatalf("next_cursor must be null on the last page, got %v", body["next_cursor"])
	}
	rows := batchRows(t, body)
	gotIDs := make([]string, 0, len(rows))
	for _, row := range rows {
		gotIDs = append(gotIDs, row["batch_id"].(string))
	}
	if strings.Join(gotIDs, ",") != "b-two,b-one,b-old" {
		t.Fatalf("batch order = %v, want b-two,b-one,b-old", gotIDs)
	}

	summary := rows[0]
	if summary["release_count"].(float64) != 2 {
		t.Fatalf("release_count = %v, want 2", summary["release_count"])
	}
	if envs := mustStringSlice(t, summary["environments"]); strings.Join(envs, ",") != "dev,prod" {
		t.Fatalf("environments = %v, want dev,prod", envs)
	}
	if summary["change_count"].(float64) != 3 {
		t.Fatalf("change_count = %v, want 3", summary["change_count"])
	}
	gateCounts := summary["gate_counts"].(map[string]any)
	if gateCounts["allowed"].(float64) != 1 || gateCounts["blocked"].(float64) != 1 ||
		gateCounts["pending"].(float64) != 0 {
		t.Fatalf("gate_counts = %v, want 1 allowed, 1 blocked, 0 pending", gateCounts)
	}
	lastAt := summary["last_recorded_at"].(string)
	if lastAt == "" || !strings.HasSuffix(lastAt, "Z") {
		t.Fatalf("last_recorded_at = %q", lastAt)
	}
}

func TestListReleaseBatchesPaginationWalksOnce(t *testing.T) {
	router := newTestRouter(t)
	seedBatchScenario(t, router)

	path := "/api/v1/release-batches?limit=2"
	var seen []string
	for page := 0; page < 10; page++ {
		recorder := doRequest(t, router, http.MethodGet, path, "")
		if recorder.Code != http.StatusOK {
			t.Fatalf("page %d status = %d (body %s)", page, recorder.Code, recorder.Body.String())
		}
		body := decodeBatchesBody(t, recorder)
		rows := batchRows(t, body)
		for _, row := range rows {
			seen = append(seen, row["batch_id"].(string))
		}
		cursor, _ := body["next_cursor"].(string)
		if cursor == "" {
			break
		}
		path = "/api/v1/release-batches?limit=2&cursor=" + cursor
	}
	if strings.Join(seen, ",") != "b-two,b-one,b-old" {
		t.Fatalf("paged walk = %v", seen)
	}
}

func TestListReleaseBatchesFiltersAreAND(t *testing.T) {
	router := newTestRouter(t)
	seedBatchScenario(t, router)

	// gate_status=pending matches only b-one; its summary still covers both records.
	recorder := doRequest(t, router, http.MethodGet,
		"/api/v1/release-batches?gate_status=pending", "")
	body := decodeBatchesBody(t, recorder)
	rows := batchRows(t, body)
	if len(rows) != 1 || rows[0]["batch_id"] != "b-one" {
		t.Fatalf("gate filter rows = %v, want only b-one", rows)
	}
	if rows[0]["release_count"].(float64) != 2 {
		t.Fatalf("b-one summary must cover both records: %v", rows[0])
	}
	gateCounts := rows[0]["gate_counts"].(map[string]any)
	if gateCounts["allowed"].(float64) != 1 || gateCounts["pending"].(float64) != 1 {
		t.Fatalf("b-one gate_counts = %v", gateCounts)
	}

	// environment + version AND; version 2.0.0 at prod keeps b-two.
	recorder = doRequest(t, router, http.MethodGet,
		"/api/v1/release-batches?environment=prod&version=2.0.0", "")
	rows = batchRows(t, body2(recorder))
	if len(rows) != 1 || rows[0]["batch_id"] != "b-two" {
		t.Fatalf("environment/version filter rows = %v, want only b-two", rows)
	}

	// Unbatched records never form a batch.
	recorder = doRequest(t, router, http.MethodGet,
		"/api/v1/release-batches?version=9.9.9", "")
	rows = batchRows(t, body2(recorder))
	if len(rows) != 0 {
		t.Fatalf("unbatched records must not appear: %v", rows)
	}
}

func body2(recorder *httptest.ResponseRecorder) map[string]any {
	return decodeBatchesBody(nil, recorder)
}

func TestListReleaseBatchesTimeBoundsInclusive(t *testing.T) {
	router := newTestRouter(t)
	seedBatchScenario(t, router)
	all := batchRows(t, decodeBatchesBody(t,
		doRequest(t, router, http.MethodGet, "/api/v1/release-batches", "")))
	if len(all) != 3 {
		t.Fatalf("seed rows = %d", len(all))
	}
	bOneAt := all[1]["last_recorded_at"].(string)

	recorder := doRequest(t, router, http.MethodGet,
		"/api/v1/release-batches?from="+bOneAt+"&to="+bOneAt, "")
	rows := batchRows(t, decodeBatchesBody(t, recorder))
