func TestListReleaseBatchesErrors(t *testing.T) {
	router := newTestRouter(t)
	registerEnvironmentOK(t, router, "prod")
	seedBatchScenario(t, router)

	cases := map[string]string{
		"gate invalid":        "/api/v1/release-batches?gate_status=yes",
		"time malformed":      "/api/v1/release-batches?from=monday",
		"time noncanonical":   "/api/v1/release-batches?to=2026-10-01T08:00:00+08:00",
		"time order":          "/api/v1/release-batches?from=2026-10-02T00:00:00Z&to=2026-10-01T00:00:00Z",
		"limit zero":          "/api/v1/release-batches?limit=0",
		"limit huge":          "/api/v1/release-batches?limit=101",
		"limit noninteger":    "/api/v1/release-batches?limit=abc",
		"limit blank":         "/api/v1/release-batches?limit=",
		"environment blank":   "/api/v1/release-batches?environment=",
		"cursor blank":        "/api/v1/release-batches?cursor=",
		"cursor malformed":    "/api/v1/release-batches?cursor=not-a-cursor",
		"cursor unsigned":     "/api/v1/release-batches?cursor=" + base64.RawURLEncoding.EncodeToString([]byte(`{"f":{},"last_recorded_at":"x","batch_id":"y"}`)),
		"cursor other filter": "",
	}
	for name, path := range cases {
		if name == "cursor other filter" {
			cursor := firstBatchCursor(t, router, "/api/v1/release-batches?gate_status=pending&limit=1")
			path = "/api/v1/release-batches?cursor=" + cursor
		}
		recorder := doRequest(t, router, http.MethodGet, path, "")
		wantError(t, recorder, http.StatusBadRequest, "BATCH_QUERY_INVALID")
	}
}

