func decodeBatchesBody(t *testing.T, recorder *httptest.ResponseRecorder) map[string]any {
	t.Helper()
	body := decodeBody(t, recorder)
	for _, key := range []string{"batches", "next_cursor"} {
		if _, ok := body[key]; !ok {
			t.Fatalf("response missing %s: %s", key, recorder.Body.String())
		}
	}
	if len(body) != 2 {
		t.Fatalf("response must contain only batches and next_cursor: %s", recorder.Body.String())
	}
	return body
}

func batchRows(t *testing.T, body map[string]any) []map[string]any {
	t.Helper()
	raw, ok := body["batches"].([]any)
	if !ok {
		t.Fatalf("batches is not an array: %v", body["batches"])
	}
	rows := make([]map[string]any, 0, len(raw))
	for _, item := range raw {
		row, ok := item.(map[string]any)
		if !ok {
			t.Fatalf("batch row is not an object: %v", item)
		}
		rows = append(rows, row)
	}
	return rows
}

func batchIDs(t *testing.T, body map[string]any) []string {
	t.Helper()
	rows := batchRows(t, body)
	ids := make([]string, 0, len(rows))
	for _, row := range rows {
		ids = append(ids, row["batch_id"].(string))
	}
	return ids
}

func batchRecordBody(environment, version, batchID, gate string, changes ...string) string {
	entries := make([]string, 0, len(changes))
	for i, title := range changes {
		entries = append(entries, fmt.Sprintf(
			`{"sequence":%d,"category":"feature","title":%q,"description":"desc %s"}`,
			i+1, title, title))
	}
	return fmt.Sprintf(
		`{"environment":%q,"version":%q,"batch_id":%q,"changes":[%s],"gate_status":%q,"rollback_point":"snap:0"}`,
		environment, version, batchID, strings.Join(entries, ","), gate)
}

