	envs, _ := alpha["environments"].([]any)
	if len(envs) != 2 || envs[0] != "dev" || envs[1] != "prod" {
		t.Fatalf("alpha environments = %v, want [dev prod]", alpha["environments"])
	}
	if alpha["change_count"].(float64) != 4 {
		t.Fatalf("alpha change_count = %v, want 4", alpha["change_count"])
	}
	gates, _ := alpha["gate_counts"].(map[string]any)
	if gates["allowed"].(float64) != 1 || gates["blocked"].(float64) != 1 || gates["pending"].(float64) != 0 {
		t.Fatalf("alpha gate_counts = %v", gates)
	}
	if alpha["last_recorded_at"].(string) == "" {
		t.Fatalf("alpha last_recorded_at empty: %v", alpha)
	}
	if _, ok := alpha["releases"]; ok {
		t.Fatalf("summary rows must not include releases: %v", alpha)
	}
