func TestListReleaseBatchesFiltersAreAND(t *testing.T) {
	router := newTestRouter(t)
	seedReleaseBatches(t, router)

	// b-alpha has no pending record; b-beta does, but only in dev.
	recorder := doRequest(t, router, http.MethodGet,
		"/api/v1/release-batches?gate_status=pending&environment=dev", "")
	if recorder.Code != http.StatusOK {
		t.Fatalf("status = %d, %s", recorder.Code, recorder.Body.String())
	}
	if got := batchIDs(t, decodeBatchesBody(t, recorder)); len(got) != 1 || got[0] != "b-beta" {
		t.Fatalf("filtered batches = %v, want [b-beta]", got)
	}

	// The qualifying batch's summary still covers every record of the batch.
	rows := batchRows(t, decodeBatchesBody(t,
		doRequest(t, router, http.MethodGet, "/api/v1/release-batches?environment=prod", "")))
	if len(rows) != 1 || rows[0]["batch_id"] != "b-alpha" {
		t.Fatalf("environment=prod batches = %v", rows)
	}
	if rows[0]["release_count"].(float64) != 2 {
		t.Fatalf("summary must cover every batch record, got release_count %v", rows[0]["release_count"])
	}

	// version filter: only b-alpha recorded version 1.0.0.
	recorder = doRequest(t, router, http.MethodGet,
		"/api/v1/release-batches?version=1.0.0", "")
	if got := batchIDs(t, decodeBatchesBody(t, recorder)); len(got) != 1 || got[0] != "b-alpha" {
		t.Fatalf("version filter batches = %v", got)
	}

	// A future bound matches nothing but is still a 200 empty page.
	recorder = doRequest(t, router, http.MethodGet,
		"/api/v1/release-batches?from=2999-01-01T00:00:00Z", "")
	if recorder.Code != http.StatusOK {
		t.Fatalf("status = %d, %s", recorder.Code, recorder.Body.String())
	}
	emptyBody := decodeBatchesBody(t, recorder)
	if len(batchRows(t, emptyBody)) != 0 || emptyBody["next_cursor"] != nil {
		t.Fatalf("empty result must be [] with null next_cursor: %s", recorder.Body.String())
	}
}

func TestListReleaseBatchesInclusiveTimeBounds(t *testing.T) {
	router := newTestRouter(t)
	seedReleaseBatches(t, router)
	records := listAllRecords(t, router)
	last := records[0]["recorded_at"].(string)
	first := records[len(records)-1]["recorded_at"].(string)

	// from == newest timestamp still includes that record's batch.
	recorder := doRequest(t, router, http.MethodGet,
		"/api/v1/release-batches?from="+last, "")
	if got := batchIDs(t, decodeBatchesBody(t, recorder)); len(got) != 1 || got[0] != "b-beta" {
		t.Fatalf("from inclusive batches = %v", got)
