func TestListReleaseBatchesPaginationWalk(t *testing.T) {
	router := newTestRouter(t)
	registerEnvironmentOK(t, router, "dev")
	const batchCount = 5
	// Distinct versions so inserts never collide on (environment, version).
	for i := 0; i < batchCount; i++ {
		createRecordOK(t, router, batchRecordBody("dev",
			fmt.Sprintf("1.%d.0", i), fmt.Sprintf("b-%d", i), "allowed", "x"))
	}

	path := "/api/v1/release-batches?limit=2"
	seen := []string{}
	for page := 0; page < 10; page++ {
		recorder := doRequest(t, router, http.MethodGet, path, "")
		if recorder.Code != http.StatusOK {
			t.Fatalf("page %d status = %d, %s", page, recorder.Code, recorder.Body.String())
		}
		body := decodeBatchesBody(t, recorder)
		seen = append(seen, batchIDs(t, body)...)
		next, _ := body["next_cursor"].(string)
		if next == "" {
			break
		}
		path = "/api/v1/release-batches?limit=2&cursor=" + next
	}
	if len(seen) != batchCount {
		t.Fatalf("walked %d batches, want %d: %v", len(seen), batchCount, seen)
	}
	unique := map[string]bool{}
	want := []string{"b-4", "b-3", "b-2", "b-1", "b-0"}
	for i, id := range seen {
		if id != want[i] {
			t.Fatalf("walk order = %v, want %v", seen, want)
		}
		unique[id] = true
	}
	if len(unique) != batchCount {
		t.Fatalf("duplicate batches in walk: %v", seen)
	}
}

func TestListReleaseBatchesCursorRejectsMismatchedFilter(t *testing.T) {
	router := newTestRouter(t)
	seedReleaseBatches(t, router)
	first := doRequest(t, router, http.MethodGet,
		"/api/v1/release-batches?environment=dev&limit=1", "")
	body := decodeBatchesBody(t, first)
	cursor, _ := body["next_cursor"].(string)
	if cursor == "" {
		t.Fatal("expected a next_cursor")
	}

	rebound := doRequest(t, router, http.MethodGet,
		"/api/v1/release-batches?environment=prod&limit=1&cursor="+cursor, "")
	wantError(t, rebound, http.StatusBadRequest, store.CodeBatchQueryInvalidV1)

	tampered := doRequest(t, router, http.MethodGet,
		"/api/v1/release-batches?environment=dev&limit=1&cursor="+cursor+"x", "")
	wantError(t, tampered, http.StatusBadRequest, store.CodeBatchQueryInvalidV1)

	parts := strings.SplitN(cursor, ".", 2)
	payload, err := base64.RawURLEncoding.DecodeString(parts[0])
	if err != nil {
		t.Fatal(err)
	}
	forged := base64.RawURLEncoding.EncodeToString(append(payload, ' ')) + "." + parts[1]
	wantError(t, doRequest(t, router, http.MethodGet,
		"/api/v1/release-batches?environment=dev&limit=1&cursor="+forged, ""),
		http.StatusBadRequest, store.CodeBatchQueryInvalidV1)
}

func TestListReleaseBatchesInvalidParams(t *testing.T) {
	router := newTestRouter(t)
	cases := map[string]string{
		"gate_status=allowednope": store.CodeBatchQueryInvalidV1,
		"gate_status=":            store.CodeBatchQueryInvalidV1,
		"from=tuesday":            store.CodeBatchQueryInvalidV1,
		"to=2026-10-01":           store.CodeBatchQueryInvalidV1,
		"from=2026-10-02T00:00:00Z&to=2026-10-01T00:00:00Z": store.CodeBatchQueryInvalidV1,
		"limit=0":    store.CodeBatchQueryInvalidV1,
		"limit=101":  store.CodeBatchQueryInvalidV1,
		"limit=abc":  store.CodeBatchQueryInvalidV1,
		"limit=":     store.CodeBatchQueryInvalidV1,
		"cursor=":    store.CodeBatchQueryInvalidV1,
		"cursor=abc": store.CodeBatchQueryInvalidV1,
		"version=":   store.CodeBatchQueryInvalidV1,
	}
	for query, code := range cases {
		recorder := doRequest(t, router, http.MethodGet,
			"/api/v1/release-batches?"+query, "")
		if recorder.Code != http.StatusBadRequest {
			t.Fatalf("%s status = %d, want 400 (body %s)", query, recorder.Code, recorder.Body.String())
		}
		wantError(t, recorder, http.StatusBadRequest, code)
	}
}

func TestListReleaseBatchesUnknownEnvironment(t *testing.T) {
	router := newTestRouter(t)
	recorder := doRequest(t, router, http.MethodGet,
		"/api/v1/release-batches?environment=ghost", "")
	wantError(t, recorder, http.StatusNotFound, store.CodeEnvironmentNotFoundV1)
}

func TestListReleaseBatchesStorageUnavailable(t *testing.T) {
	router, db := newBatchTestRouter(t)
	registerEnvironmentOK(t, router, "prod")
	if err := db.Close(); err != nil {
		t.Fatal(err)
	}
	wantError(t, doRequest(t, router, http.MethodGet,
		"/api/v1/release-batches?environment=prod", ""),
		http.StatusServiceUnavailable, store.CodeStorageUnavailable)
}

func newBatchTestRouter(t *testing.T) (*gin.Engine, *store.Store) {
	t.Helper()
	gin.SetMode(gin.TestMode)
	db, err := store.Open(t.TempDir() + "/batch.db")
	if err != nil {
		t.Fatalf("open store: %v", err)
	}
	t.Cleanup(func() { db.Close() })
	engine := gin.New()
	Register(engine, Dependencies{Store: db})
	return engine, db
}

