// plus one unbatched prod 9.0.0 record that must never appear.
func seedReleaseBatchFixture(t *testing.T, router *gin.Engine) {
	t.Helper()
	for _, env := range []string{"dev", "staging", "prod"} {
		registerEnvironmentOK(t, router, env)
	}
	createRecordOK(t, router, batchRecordBody("prod", "1.0.0", "b-1", "allowed", "alpha"))
	createRecordOK(t, router, batchRecordBody("staging", "1.0.0", "b-1", "blocked", "beta"))
	createRecordOK(t, router, batchRecordBody("dev", "1.0.0", "b-2", "allowed", "alpha", "gamma"))
	createRecordOK(t, router, batchRecordBody("prod", "1.0.0", "b-2", "pending"))
	createRecordOK(t, router, unbatchedRecordBody("prod", "9.0.0"))
}

