package store

import (
	"errors"
	"path/filepath"
	"testing"
)

func sampleRecord(environment, version, gate, rollback string, changes ...ChangeEntry) *ReleaseRecord {
	return &ReleaseRecord{
		Environment:   environment,
		Version:       version,
		GateStatus:    gate,
		RollbackPoint: rollback,
		Changes:       changes,
	}
}

func entries(titles ...string) []ChangeEntry {
	out := make([]ChangeEntry, 0, len(titles))
	for i, title := range titles {
		out = append(out, ChangeEntry{Sequence: i + 1, Category: "change", Title: title, Description: "desc " + title})
	}
	return out
}

func TestEnsureEnvironmentIdempotentAndList(t *testing.T) {
	db := openTestStore(t)
	first := &TrackedEnvironment{Environment: "prod", DisplayName: "Production"}
	created, err := db.EnsureEnvironment(first)
	if err != nil || !created || first.RegisteredAt == "" {
		t.Fatalf("first ensure = %v, %v; want created with timestamp", first, err)
	}
	again := &TrackedEnvironment{Environment: "prod", DisplayName: "Ignored"}
	created, err = db.EnsureEnvironment(again)
	if err != nil || created {
		t.Fatalf("second ensure = %v, %v; want idempotent no-op", again, err)
	}
	if again.DisplayName != "Production" || again.RegisteredAt != first.RegisteredAt {
		t.Fatalf("idempotent ensure changed the row: %+v", again)
		}
	}
	// Insert several batched facts for dev sharing one recorded_at second.
	// ListReleaseRecords is newest-first; reversing must recover write order.
	insert := func(version string) {
		t.Helper()
		record := sampleRecord("dev", version, "allowed", "rb:0.9.0", entries("a:"+version)...)
		record.BatchID = "batch-time"
		if err := db.InsertReleaseRecord(record); err != nil {
			t.Fatalf("insert %s: %v", version, err)
		}
	}
	insert("1.0.0")
	insert("1.0.1")
	insert("1.0.2")
	listed, err := db.ListReleaseRecords(ReleaseRecordFilter{BatchID: "batch-time", Environment: "dev"})
	if err != nil || len(listed) != 3 {
		t.Fatalf("list = %+v, %v", listed, err)
	}
	if listed[0].Version != "1.0.2" || listed[2].Version != "1.0.0" {
		t.Fatalf("newest-first order = %s, %s, %s", listed[0].Version, listed[1].Version, listed[2].Version)
	}
	// Reversing yields chronological write order, the order chain nodes use.
	if listed[len(listed)-1].Version != "1.0.0" || listed[0].Version != "1.0.2" {
		t.Fatalf("reversed order must be 1.0.0..1.0.2")
	}
	exists, err := db.ReleaseBatchExists("batch-time")
	if err != nil || !exists {
		t.Fatalf("exists = %v, %v", exists, err)
	}
}

